relacoes: {"destino_id": "n_e659", "fonte_refs": [{"fonte_id": "f_e847b102df", "localizador": "L02"}], "id": "l_8a19", "lag_dias": 0, "origem_id": "n_08df", "tipo": "precede_FS"}
